/* Language: English by default, Spanish on every page under /es/ (generated by scripts/build_es.py).
   The EN/ES button swaps /es/ in and out of the current URL, so you stay on the same page. */
(function(){
var lang=(document.documentElement.lang||"en").slice(0,2)==="es"?"es":"en";
var pre=lang==="es"?"/es":"";
var STR={
en:{primary:"Primary",professional:"Professional",travel:"Travel",mountains:"Mountains",diving:"Diving",wildlife:"Wildlife",photography:"Photography",contact:"Contact",search:"Search the site",searchTitle:"Search (press /)",dark:"Toggle dark mode",toDark:"Switch to dark mode",toLight:"Switch to light mode",openMenu:"Open menu",closeMenu:"Close menu",switchLabel:"Ver esta página en español",switchText:"ES",switchLang:"es"},
es:{primary:"Principal",professional:"Profesional",travel:"Viajes",mountains:"Montañas",diving:"Buceo",wildlife:"Fauna",photography:"Fotografía",contact:"Contacto",search:"Buscar en el sitio",searchTitle:"Buscar (pulsa /)",dark:"Alternar modo oscuro",toDark:"Cambiar a modo oscuro",toLight:"Cambiar a modo claro",openMenu:"Abrir menú",closeMenu:"Cerrar menú",switchLabel:"View this page in English",switchText:"EN",switchLang:"en"}
}[lang];
var C={"Belgium":"Bélgica","Canada":"Canadá","Croatia":"Croacia","France":"Francia","Germany":"Alemania","Hungary":"Hungría","Italy":"Italia","Japan":"Japón","Jordan":"Jordania","Kazakhstan":"Kazajistán","Malaysia":"Malasia","Mexico":"México","Monaco":"Mónaco","Morocco":"Marruecos","Netherlands":"Países Bajos","Oman":"Omán","Philippines":"Filipinas","Poland":"Polonia","Singapore":"Singapur","Slovakia":"Eslovaquia","Spain":"España","Thailand":"Tailandia","Turkey":"Turquía","United Arab Emirates":"Emiratos Árabes Unidos","United Kingdom":"Reino Unido","United States":"Estados Unidos","Uzbekistan":"Uzbekistán","Vatican City":"Ciudad del Vaticano","New Zealand":"Nueva Zelanda"};
var p=location.pathname.replace(/index\.html$/,"");
var twin=(lang==="es"?(p.replace(/^\/es(?=\/|$)/,"")||"/"):("/es"+(p==="/"?"/":p)))+location.search+location.hash;
window.__i18n={lang:lang,s:STR,pre:pre,country:function(n){return lang==="es"&&C[n]?C[n]:n}};
window.__i18nTwin=twin;
/* Keep people in Spanish: any internal page link (also ones created later by scripts) points at /es/. */
if(lang==="es"){
var fix=function(root){(root||document).querySelectorAll('a[href^="/"]').forEach(function(a){var h=a.getAttribute("href");if(a.classList.contains("lang-switch")||h.indexOf("//")===0||/^\/(es|assets|data|js)(\/|$)/.test(h)||/\.[a-z0-9]{2,5}([?#]|$)/i.test(h.split("#")[0].replace(/index\.html$/,"")))return;a.setAttribute("href","/es"+(h==="/"?"/":h.replace(/^\/index\.html/,"/")))})};
var tm;var run=function(){clearTimeout(tm);tm=setTimeout(function(){fix()},30)};
document.addEventListener("DOMContentLoaded",function(){fix();new MutationObserver(run).observe(document.body,{childList:true,subtree:true})});
}
})();

document.addEventListener("DOMContentLoaded",()=>{const nav=document.querySelector("#nav");if(nav){const I=window.__i18n,S=I.s,P=I.pre;const pr=(u)=>P+u;nav.innerHTML=`<header class="site-header"><nav class="nav shell" aria-label="${S.primary}"><a class="logo" href="${P?P+"/":"/index.html"}">ACM<span></span></a><div class="navlinks"><a href="${pr("/professional/")}">${S.professional}</a><a href="${P}/travel/">${S.travel}</a><a href="${pr("/mountains/")}">${S.mountains}</a><a href="${P}/diving/">${S.diving}</a><a href="${P}/wildlife/">${S.wildlife}</a><a href="${P}/photography/">${S.photography}</a></div><a class="nav-cta" href="${pr("/contact/")}">${S.contact}</a><a class="lang-switch" href="${window.__i18nTwin}" hreflang="${S.switchLang}" lang="${S.switchLang}" aria-label="${S.switchLabel}" title="${S.switchLabel}">${S.switchText}</a><button class="search-btn" type="button" aria-label="${S.search}" title="${S.searchTitle}"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/></svg></button><button class="theme-toggle" type="button" aria-label="${S.dark}"></button><button class="menu" type="button" aria-label="${S.openMenu}" aria-expanded="false">☰</button></nav></header>`;const m=nav.querySelector(".menu"),l=nav.querySelector(".navlinks");m.onclick=()=>{const open=l.dataset.open==="1";l.dataset.open=open?"0":"1";m.setAttribute("aria-expanded",open?"false":"true");m.setAttribute("aria-label",open?S.openMenu:S.closeMenu);l.style.cssText=open?"":"display:flex;position:absolute;top:76px;left:0;right:0;padding:20px;background:var(--bg);flex-direction:column;gap:17px;border-bottom:1px solid var(--line)"};}const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add("show")}),{threshold:.1});document.querySelectorAll(".reveal").forEach(e=>io.observe(e));});

document.addEventListener("DOMContentLoaded",()=>{const b=document.querySelector(".theme-toggle");if(!b)return;const mq=window.matchMedia("(prefers-color-scheme: dark)");const eff=()=>document.documentElement.dataset.theme||(mq.matches?"dark":"light");const paint=()=>{const d=eff()==="dark";b.textContent=d?"☀":"☾";b.title=d?window.__i18n.s.toLight:window.__i18n.s.toDark};b.addEventListener("click",()=>{const n=eff()==="dark"?"light":"dark";document.documentElement.dataset.theme=n;try{localStorage.setItem("theme",n)}catch(e){}paint()});mq.addEventListener&&mq.addEventListener("change",paint);paint()});

document.addEventListener("DOMContentLoaded",()=>{const p=location.pathname.replace(/index\.html$/,"");document.querySelectorAll(".navlinks a").forEach(a=>{const h=a.getAttribute("href").replace(/index\.html$/,"");if(h!=="/"&&(p===h||p.startsWith(h)))a.setAttribute("aria-current","page")})});
/* Privacy-friendly, cookieless stats (GoatCounter). Create a free site at goatcounter.com, then put its code here, e.g. var GC="albercm30". Leave empty to keep stats off. */
(function(){var GC="albercm30";if(!GC||location.hostname!=="albercm30.github.io")return;var s=document.createElement("script");s.async=true;s.src="https://gc.zgo.at/count.js";s.setAttribute("data-goatcounter","https://"+GC+".goatcounter.com/count");document.head.appendChild(s)})();

(function(){const open=()=>{if(window.__siteSearch){window.__siteSearch.open();return}const s=document.createElement("script");s.src="/js/search.js";document.head.appendChild(s)};
document.addEventListener("click",e=>{if(e.target.closest&&e.target.closest(".search-btn"))open()});
document.addEventListener("keydown",e=>{const t=e.target,typing=t&&(t.tagName==="INPUT"||t.tagName==="TEXTAREA"||t.tagName==="SELECT"||t.isContentEditable);if(((e.key==="/"&&!typing)||((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"))&&!(window.__siteSearch&&!document.querySelector(".search-overlay").hidden)){e.preventDefault();open()}})})();

/* Click any gallery photo to enlarge it (arrows / swipe / Esc). */
(function(){
var I=window.__i18n||{lang:"en"},ES=I.lang==="es";
var L=ES?{close:"Cerrar",prev:"Anterior",next:"Siguiente",of:"de",enlarge:"ampliar"}:{close:"Close",prev:"Previous",next:"Next",of:"of",enlarge:"enlarge"};
document.addEventListener("DOMContentLoaded",function(){
var imgs=[].slice.call(document.querySelectorAll(".photo-tile > img"));
if(!imgs.length)return;
var box,img,cap,cur=0,opener=null,x0=null;
imgs.forEach(function(im,i){var t=im.parentNode;t.tabIndex=0;t.setAttribute("role","button");t.setAttribute("aria-label",(im.alt||"")+" ("+L.enlarge+")");
t.addEventListener("click",function(){open(i,t)});
t.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();open(i,t)}})});
function mk(tag,cls,txt,lab){var e=document.createElement(tag);if(cls)e.className=cls;if(txt)e.textContent=txt;if(lab){e.setAttribute("aria-label",lab);e.type="button"}return e}
function build(){
box=mk("div","lb");box.setAttribute("role","dialog");box.setAttribute("aria-modal","true");
img=document.createElement("img");cap=mk("div","lb-cap");
var c=mk("button","lb-close","✕",L.close),p=mk("button","lb-prev","‹",L.prev),n=mk("button","lb-next","›",L.next);
box.append(img,cap,c,p,n);document.body.appendChild(box);
c.onclick=close;p.onclick=function(e){e.stopPropagation();show(cur-1)};n.onclick=function(e){e.stopPropagation();show(cur+1)};
box.addEventListener("click",function(e){if(e.target===box||e.target===cap)close()});
box.addEventListener("touchstart",function(e){x0=e.touches[0].clientX},{passive:true});
box.addEventListener("touchend",function(e){if(x0===null)return;var d=e.changedTouches[0].clientX-x0;x0=null;if(Math.abs(d)>50)show(cur+(d<0?1:-1))});
document.addEventListener("keydown",function(e){if(!box.classList.contains("open"))return;
if(e.key==="Escape")close();else if(e.key==="ArrowLeft")show(cur-1);else if(e.key==="ArrowRight")show(cur+1)});
}
function show(i){cur=(i+imgs.length)%imgs.length;var s=imgs[cur];img.classList.remove("on");
var full=s.currentSrc||s.src;img.onload=function(){img.classList.add("on")};img.src=full;img.alt=s.alt||"";
cap.innerHTML="";cap.appendChild(document.createTextNode(s.alt||""));var sm=document.createElement("small");sm.textContent=(cur+1)+" "+L.of+" "+imgs.length;cap.appendChild(sm);
[1,-1].forEach(function(d){var o=imgs[(cur+d+imgs.length)%imgs.length];if(o){var pre=new Image();pre.src=o.currentSrc||o.src}})}
function open(i,from){if(!box)build();opener=from;box.classList.add("open");document.documentElement.style.overflow="hidden";show(i);box.querySelector(".lb-close").focus()}
function close(){box.classList.remove("open");document.documentElement.style.overflow="";img.removeAttribute("src");if(opener)opener.focus()}
});
})();
